from typing import List, Tuple, Dict
from textkit.extract_headings import extract_headings
from textkit.slugify import slugify


def table_of_contents(markdown: str, max_level: int = 3) -> str:
    if max_level < 1 or max_level > 6:
        raise ValueError("max_level must be between 1 and 6")

    headings = extract_headings(markdown)

    if not headings:
        return ""

    # First pass: count occurrences of each slug across ALL headings
    slug_counts: Dict[str, int] = {}
    heading_occurrence: List[int] = []

    for level, title in headings:
        base_anchor = slugify(title)
        if not base_anchor:
            heading_occurrence.append(-1)
            continue
        if base_anchor not in slug_counts:
            slug_counts[base_anchor] = 0
        slug_counts[base_anchor] += 1
        heading_occurrence.append(slug_counts[base_anchor])

    # Second pass: build TOC from filtered headings
    filtered = [(i, level, title) for i, (level, title) in enumerate(headings) if level <= max_level]

    if not filtered:
        return ""

    min_level = min(level for _, level, _ in filtered)

    lines = []
    for idx, level, title in filtered:
        base_anchor = slugify(title)
        if not base_anchor:
            continue

        occ = heading_occurrence[idx]
        if occ == 1:
            anchor = base_anchor
        else:
            anchor = f"{base_anchor}-{occ - 1}"

        indent = "  " * (level - min_level)
        lines.append(f"{indent}- [{title}](#{anchor})")

    return "\n".join(lines)
